<?php
require __DIR__.'/config.php'; require_login(); $pdo=db();
$todaySales=(float)$pdo->query("SELECT COALESCE(SUM(total),0) FROM sales WHERE DATE(created_at)=CURDATE() AND status<>'void'")->fetchColumn();
$todayProfit=(float)$pdo->query("SELECT COALESCE(SUM(si.quantity*(si.unit_price-si.unit_cost)),0) FROM sale_items si JOIN sales s ON s.id=si.sale_id WHERE DATE(s.created_at)=CURDATE() AND s.status<>'void'")->fetchColumn();
$todayExpenses=(float)$pdo->query("SELECT COALESCE(SUM(amount),0) FROM expenses WHERE expense_date=CURDATE()")->fetchColumn();
$outstandingDebt=(float)$pdo->query("SELECT COALESCE(SUM(total-amount_paid),0) FROM sales WHERE status='utang'")->fetchColumn();
$utangCustomers=(int)$pdo->query("SELECT COUNT(DISTINCT customer_id) FROM sales WHERE status='utang' AND customer_id IS NOT NULL")->fetchColumn();
$productCount=(int)$pdo->query("SELECT COUNT(*) FROM products WHERE active=1")->fetchColumn();
// Outstanding debt is based on the unpaid balance, not only the status label.
$totalOutstanding=(float)$pdo->query("SELECT COALESCE(SUM(GREATEST(total-amount_paid,0)),0) FROM sales WHERE status<>'void' AND (status='utang' OR payment_method='utang') AND total>amount_paid")->fetchColumn();
$customersWithDebt=(int)$pdo->query("SELECT COUNT(DISTINCT customer_id) FROM sales WHERE customer_id IS NOT NULL AND status<>'void' AND (status='utang' OR payment_method='utang') AND total>amount_paid")->fetchColumn();
$lowStock=$pdo->query("SELECT name,stock,reorder_level FROM products WHERE active=1 AND stock<=reorder_level ORDER BY stock ASC LIMIT 8")->fetchAll();
$recent=$pdo->query("SELECT s.id,s.receipt_no,s.total,s.status,s.payment_method,s.created_at,COALESCE(c.name,'Walk-in') customer FROM sales s LEFT JOIN customers c ON c.id=s.customer_id WHERE s.status<>'void' ORDER BY s.id DESC LIMIT 6")->fetchAll();
$week=$pdo->query("SELECT DATE(created_at) day,COALESCE(SUM(total),0) total FROM sales WHERE created_at>=CURDATE()-INTERVAL 6 DAY AND status<>'void' GROUP BY DATE(created_at)")->fetchAll();
$weekMap=[]; foreach($week as $w)$weekMap[$w['day']]=(float)$w['total'];
$pageTitle='Dashboard'; require __DIR__.'/partials/header.php';
?>
<div class="welcome"><div><span class="eyebrow">STORE OVERVIEW · <?=e(date('F j, Y'))?></span><h1>Welcome back, <?=e(current_user()['name'])?> 👋</h1><p>Your store's sales, stock, and daily operations at a glance.</p></div><a class="btn light" href="pos.php">▣ Open POS Register →</a></div>
<div class="stats-grid"><article class="stat-card"><div class="stat-top"><span>Outstanding Utang</span><span class="stat-icon amber">₱</span></div><strong><?=money($totalOutstanding)?></strong><small><?=number_format($customersWithDebt)?> customers with unpaid balances</small></article><article class="stat-card"><div class="stat-top"><span>Today's Total Sales</span><span class="stat-icon red">₱</span></div><strong><?=money($todaySales)?></strong><small>Completed and utang sales</small></article><article class="stat-card"><div class="stat-top"><span>Estimated Gross Profit</span><span class="stat-icon green">↗</span></div><strong><?=money($todayProfit)?></strong><small>Before operating expenses</small></article><article class="stat-card"><div class="stat-top"><span>Today's Expenses</span><span class="stat-icon amber">−</span></div><strong><?=money($todayExpenses)?></strong><small>Recorded expenses</small></article><article class="stat-card"><div class="stat-top"><span>Total Outstanding Utang</span><span class="stat-icon amber">₱</span></div><strong><?=money($outstandingDebt)?></strong><small><?=$utangCustomers?> customers with unpaid balances</small></article><article class="stat-card"><div class="stat-top"><span>Active Products</span><span class="stat-icon blue">▤</span></div><strong><?=number_format($productCount)?></strong><small><?=count($lowStock)?> low-stock products listed</small></article></div>
<div class="dashboard-grid"><article class="panel"><div class="panel-heading"><div><h2>7-Day Sales Performance</h2><p>Daily sales total</p></div><a href="reports.php">Full reports →</a></div><div class="chart"><?php for($i=6;$i>=0;$i--):$day=date('Y-m-d',strtotime("-$i days"));$v=$weekMap[$day]??0;$max=max(array_merge([1],array_values($weekMap)));?><div class="chart-col"><strong><?=money($v)?></strong><div class="bar-wrap"><div class="bar" style="height:<?=max(3,($v/$max)*100)?>%"></div></div><small><?=date('D',strtotime($day))?></small></div><?php endfor; ?></div></article><article class="panel"><div class="panel-heading"><div><h2>Quick Store Actions</h2><p>Shortcuts for daily tasks</p></div></div><div class="quick-actions"><a href="pos.php"><span class="quick-icon">▣</span><span><b>New Sale (POS)</b><small>Record a customer purchase</small></span>›</a><a href="products.php"><span class="quick-icon gray">▤</span><span><b>Stock & Inventory</b><small>Add products or adjust stock</small></span>›</a><a href="customers.php"><span class="quick-icon blue">♙</span><span><b>Customers & Utang</b><small>Track balances and payments</small></span>›</a><a href="expenses.php"><span class="quick-icon amber">₱</span><span><b>Record Expense</b><small>Log bills, supplies, and fare</small></span>›</a></div><div class="system-status"><span>System status</span><b>● Ready</b></div></article></div>
<div class="dashboard-grid lower-grid"><article class="panel"><div class="panel-heading"><div><h2>Recent Transactions</h2><p>Latest store activity</p></div><a href="reports.php">View all →</a></div><div class="table-wrap"><table><thead><tr><th>Receipt</th><th>Customer</th><th>Total</th><th>Payment</th><th>Status</th></tr></thead><tbody><?php if(!$recent): ?><tr><td colspan="5" class="empty">No sales yet. Start with New Sale.</td></tr><?php endif; foreach($recent as $r): ?><tr><td><b><?=e($r['receipt_no'])?></b><small><?=e(date('M j, g:i A',strtotime($r['created_at'])))?></small></td><td><?=e($r['customer'])?></td><td><?=money($r['total'])?></td><td><?=e(strtoupper($r['payment_method']))?></td><td><span class="pill <?=e($r['status'])?>"><?=e(ucfirst($r['status']))?></span></td></tr><?php endforeach; ?></tbody></table></div></article><article class="panel"><div class="panel-heading"><div><h2>Low Stock Alerts</h2><p>Products to restock</p></div><a href="products.php">Inventory →</a></div><?php if(!$lowStock): ?><p class="empty">All products are above their reorder levels.</p><?php else: ?><div class="stock-list"><?php foreach($lowStock as $p): ?><div><span><b><?=e($p['name'])?></b><small>Reorder level: <?=e($p['reorder_level'])?></small></span><span class="stock-count"><?=e($p['stock'])?> left</span></div><?php endforeach; ?></div><?php endif; ?></article></div>
<?php require __DIR__.'/partials/footer.php'; ?>